// pyrepr.mjs — mimic CPython repr()/str() of decoded-JSON values for print().

// Approximation of CPython's str.isprintable() for the code points that
// matter: control chars, line/paragraph separators, space separators other
// than U+0020, and common format chars are NOT printable; everything else
// (including printable non-ASCII like 中文) stays literal.
function isPrintable(cp) {
  if (cp < 0x20 || (cp >= 0x7f && cp <= 0xa0)) return false; // Cc + DEL/C1 + NBSP(Zs)
  if (cp === 0xad) return false; // SOFT HYPHEN (Cf)
  if (cp === 0x1680 || (cp >= 0x2000 && cp <= 0x200a) || cp === 0x202f || cp === 0x205f || cp === 0x3000) return false; // Zs
  if (cp === 0x2028 || cp === 0x2029) return false; // Zl, Zp
  if (cp >= 0x200b && cp <= 0x200f) return false; // Cf (ZWSP..RLM)
  if (cp >= 0x202a && cp <= 0x202e) return false; // Cf (bidi embeddings)
  if (cp >= 0x2060 && cp <= 0x2064) return false; // Cf (word joiner etc.)
  if (cp === 0xfeff) return false; // Cf (BOM/ZWNBSP)
  if (cp >= 0xd800 && cp <= 0xdfff) return false; // surrogates
  return true;
}

function escapeCodePoint(cp) {
  if (cp <= 0xff) return '\\x' + cp.toString(16).padStart(2, '0');
  if (cp <= 0xffff) return '\\u' + cp.toString(16).padStart(4, '0');
  return '\\U' + cp.toString(16).padStart(8, '0');
}

export function pyReprStr(s) {
  // CPython: prefer single quotes; use double quotes only if the string
  // contains a single quote and no double quote.
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";

  let out = quote;
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (!isPrintable(cp)) out += escapeCodePoint(cp);
    else out += ch;
  }
  return out + quote;
}

function pyReprNumber(n) {
  if (Number.isInteger(n)) {
    // JSON integers decode to Python int; print plainly.
    if (Number.isSafeInteger(n)) return String(n);
    return String(n); // best effort for huge magnitudes
  }
  // Float: Python uses repr-shortest; JS Number#toString is also shortest.
  // Normalize exponent form: JS "1e+21" matches Python "1e+21".
  return String(n);
}

export function pyRepr(value) {
  if (value === null || value === undefined) return 'None';
  if (value === true) return 'True';
  if (value === false) return 'False';
  if (typeof value === 'string') return pyReprStr(value);
  if (typeof value === 'number') return pyReprNumber(value);
  if (Array.isArray(value)) {
    return '[' + value.map(pyRepr).join(', ') + ']';
  }
  if (typeof value === 'object') {
    const items = Object.keys(value).map(
      (k) => pyReprStr(k) + ': ' + pyRepr(value[k])
    );
    return '{' + items.join(', ') + '}';
  }
  return String(value);
}

// argparse.mjs — minimal emulation of:
//   parser = argparse.ArgumentParser()
//   parser.add_argument('--subject', type=str, required=True)
//   parser.add_argument('--user_data', type=str, required=True)
// matching CPython argparse's exact messages, streams, and exit codes.

const OPTION_DEFS = [
  { name: '--subject', dest: 'subject', metavar: 'SUBJECT' },
  { name: '--user_data', dest: 'user_data', metavar: 'USER_DATA' },
];

function usageLine(prog) {
  return `usage: ${prog} [-h] --subject SUBJECT --user_data USER_DATA`;
}

function helpText(prog) {
  return (
    usageLine(prog) +
    '\n\noptions:\n' +
    '  -h, --help            show this help message and exit\n' +
    '  --subject SUBJECT\n' +
    '  --user_data USER_DATA\n'
  );
}

function error(prog, message) {
  process.stderr.write(usageLine(prog) + '\n');
  process.stderr.write(`${prog}: error: ${message}\n`);
  process.exit(2);
}

// argparse treats a token as an option string if it starts with '-' and is
// not a negative number (no defined options look like negative numbers).
function looksLikeOption(token) {
  return token.length > 1 && token[0] === '-' && !/^-\d/.test(token);
}

export function parseArgs(argv, prog) {
  const values = {};
  const extras = [];

  let i = 0;
  while (i < argv.length) {
    let token = argv[i];
    let inlineValue = null;

    // Split --opt=value form.
    if (token.startsWith('--')) {
      const eq = token.indexOf('=');
      if (eq !== -1) {
        inlineValue = token.slice(eq + 1);
        token = token.slice(0, eq);
      }
    }

    if (token === '-h' || token === '--help') {
      process.stdout.write(helpText(prog));
      process.exit(0);
    }

    // Exact match, else unambiguous prefix match (argparse allow_abbrev).
    let def = OPTION_DEFS.find((d) => d.name === token);
    if (!def && token.startsWith('--')) {
      const matches = OPTION_DEFS.filter((d) => d.name.startsWith(token));
      if (matches.length === 1) def = matches[0];
    }

    if (!def) {
      extras.push(inlineValue !== null ? `${token}=${inlineValue}` : token);
      i += 1;
      continue;
    }

    if (inlineValue !== null) {
      values[def.dest] = inlineValue;
      i += 1;
      continue;
    }

    const next = argv[i + 1];
    if (next === undefined || looksLikeOption(next)) {
      error(prog, `argument ${def.name}: expected one argument`);
    }
    values[def.dest] = next;
    i += 2;
  }

  // Required-argument check happens before the unrecognized-argument check
  // (parse_known_args validates required; parse_args reports extras after).
  const missing = OPTION_DEFS.filter((d) => !(d.dest in values)).map((d) => d.name);
  if (missing.length > 0) {
    error(prog, `the following arguments are required: ${missing.join(', ')}`);
  }
  if (extras.length > 0) {
    error(prog, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return { subject: values.subject, user_data: values.user_data };
}

import { pyRepr } from '/output/lib/pyrepr.mjs';
import { execFileSync } from 'node:child_process';
import { writeFileSync } from 'node:fs';

let failures = 0;
function eq(actual, expected, label) {
  const ok = actual === expected;
  if (!ok) failures++;
  console.log((ok ? 'PASS' : 'FAIL') + ' | ' + label);
  if (!ok) {
    console.log('  expected: ' + JSON.stringify(expected));
    console.log('  actual:   ' + JSON.stringify(actual));
  } else {
    console.log('  -> ' + JSON.stringify(actual));
  }
}

// ---- pyRepr ----
eq(pyRepr({a: 1, b: 'x'}), "{'a': 1, 'b': 'x'}", 'dict basic');
eq(pyRepr([1, 'two', true, null]), "[1, 'two', True, None]", 'list basic');
eq(pyRepr("it's"), '"it\'s"', 'single quote -> double quotes');
eq(pyRepr('say "hi"'), '\'say "hi"\'', 'double quote only -> single quotes');
eq(pyRepr('both \' and "'), '\'both \\\' and "\'', 'both quotes -> single + escape');
eq(pyRepr('back\\slash'), "'back\\\\slash'", 'backslash');
eq(pyRepr('a\nb\rc\td'), "'a\\nb\\rc\\td'", 'n r t escapes');
eq(pyRepr('�'), "'\\x00\\x1f'", 'control chars');
eq(pyRepr(' '), "'\\x7f\\xa0'", 'DEL + NBSP');
eq(pyRepr('中文'), "'中文'", 'printable non-ASCII literal');
eq(pyRepr('é'), "'\\xe9'".replace('\\x', 'é') && "'é'", 'latin-1 printable literal');
eq(pyRepr('​'), "'\\u200b'", 'ZWSP escaped');
eq(pyRepr('😀'), "'😀'", 'emoji literal');
eq(pyRepr(true), 'True', 'true');
eq(pyRepr(false), 'False', 'false');
eq(pyRepr(null), 'None', 'null');
eq(pyRepr(42), '42', 'int');
eq(pyRepr(-3.5), '-3.5', 'float');
eq(pyRepr({}), '{}', 'empty dict');
eq(pyRepr([]), '[]', 'empty list');
eq(pyRepr({nested: {x: [1, {y: 'z'}]}}), "{'nested': {'x': [1, {'y': 'z'}]}}", 'nested');

// ---- argparse (subprocess) ----
const runner = '/tmp/argparse_runner.mjs';
writeFileSync(runner,
  "import { parseArgs } from '/output/lib/argparse.mjs';\n" +
  "const [prog, ...argv] = process.argv.slice(2);\n" +
  "console.log(JSON.stringify(parseArgs(argv, prog)));\n");

function run(args) {
  try {
    const stdout = execFileSync('node', [runner, 'PROG', ...args], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
    return { code: 0, stdout, stderr: '' };
  } catch (e) {
    return { code: e.status, stdout: e.stdout ?? '', stderr: e.stderr ?? '' };
  }
}

const USAGE = 'usage: PROG [-h] --subject SUBJECT --user_data USER_DATA\n';
const HELP = USAGE + '\noptions:\n' +
  '  -h, --help            show this help message and exit\n' +
  '  --subject SUBJECT\n' +
  '  --user_data USER_DATA\n';

let r;
r = run(['--subject', 's', '--user_data', 'u']);
eq(r.code === 0 && r.stdout, JSON.stringify({subject: 's', user_data: 'u'}) + '\n', 'args: space form (exit ' + r.code + ')');
r = run(['--subject=s', '--user_data=u']);
eq(r.code === 0 && r.stdout, JSON.stringify({subject: 's', user_data: 'u'}) + '\n', 'args: = form (exit ' + r.code + ')');
r = run(['-h']);
eq(r.code, 0, 'help exit code');
eq(r.stdout, HELP, 'help stdout exact');
eq(r.stderr, '', 'help stderr empty');
r = run(['--help']);
eq(r.code === 0 && r.stdout === HELP, true, '--help same as -h');
r = run(['--subject', 's']);
eq(r.code, 2, 'missing user_data exit');
eq(r.stderr, USAGE + 'PROG: error: the following arguments are required: --user_data\n', 'missing user_data stderr');
r = run([]);
eq(r.stderr, USAGE + 'PROG: error: the following arguments are required: --subject, --user_data\n', 'both missing order');
r = run(['--subject', 's', '--user_data', 'u', '--extra', 'c']);
eq(r.code, 2, 'unrecognized exit');
eq(r.stderr, USAGE + 'PROG: error: unrecognized arguments: --extra c\n', 'unrecognized stderr');
r = run(['--subject']);
eq(r.code, 2, 'no value exit');
eq(r.stderr, USAGE + 'PROG: error: argument --subject: expected one argument\n', 'no value stderr');
r = run(['--subject', '--user_data', 'u']);
eq(r.stderr, USAGE + 'PROG: error: argument --subject: expected one argument\n', 'option-like next token');

console.log(failures === 0 ? 'ALL PASS' : failures + ' FAILURES');
process.exit(failures === 0 ? 0 : 1);
